INSERT INTO events (event_id,name,description,organizer,created_at) VALUES
(1,'Thunderstorm','A campus production of Cao Yu''s classic family tragedy.','DSC Drama Society',DATE_SUB(NOW(3), INTERVAL 29000 MINUTE)),
(2,'City Sound: String Quartet','A chamber concert of strings and piano with an interval.','DSC Music Society',DATE_SUB(NOW(3), INTERVAL 28000 MINUTE)),
(3,'Four Seasons Dance','A contemporary dance suite in eight movements.','DSC Dance Society',DATE_SUB(NOW(3), INTERVAL 27000 MINUTE)),
(4,'Late Night Comedy','Stand-up and improvised sketches in English and Cantonese.','DSC Comedy Club',DATE_SUB(NOW(3), INTERVAL 26000 MINUTE)),
(5,'Jazz in the Black Box','A small ensemble jazz night with a guest vocalist.','DSC Jazz Band',DATE_SUB(NOW(3), INTERVAL 25000 MINUTE)),
(6,'The Little Star','A children''s theatre piece about a star that lost its light.','DSC Drama Society',DATE_SUB(NOW(3), INTERVAL 24000 MINUTE)),
(7,'Opera Gala: La Traviata Highlights','Selected scenes and arias from Verdi''s opera.','DSC Opera Ensemble',DATE_SUB(NOW(3), INTERVAL 23000 MINUTE)),
(8,'Digital Light Showcase','Generative visuals and sound by the media lab.','DSC Media Lab',DATE_SUB(NOW(3), INTERVAL 22000 MINUTE));
